diff --git a/src/utils/sanitize-html.ts b/src/utils/sanitize-html.ts
new file mode 100644
index 0000000..h7i8j9k
--- /dev/null
+++ b/src/utils/sanitize-html.ts
@@ -0,0 +1,85 @@
+/**
+ * HTML sanitization utility for embed content
+ * Prevents XSS by allowing only safe tags, attributes, and styles
+ */
+
+interface SanitizeOptions {
+  allowedTags: string[];
+  allowedAttributes: Record<string, string[]>;
+  allowedSchemes: string[];
+  allowedStyles: string[];
+}
+
+const DEFAULT_OPTIONS: SanitizeOptions = {
+  allowedTags: ["b", "i", "em", "strong", "a", "p", "br", "span", "div", "img"],
+  allowedAttributes: {
+    "a": ["href", "target", "rel"],
+    "img": ["src", "alt", "width", "height"],
+    "*": ["class", "style"]
+  },
+  allowedSchemes: ["http", "https", "data"],
+  allowedStyles: ["color", "font-size", "text-align", "margin", "padding"]
+};
+
+/**
+ * Sanitizes HTML string for safe use in iframe srcdoc
+ */
+export function sanitizeHtml(html: string, options: Partial<SanitizeOptions> = {}): string {
+  const opts = { ...DEFAULT_OPTIONS, ...options };
+  
+  // Create a temporary DOM parser
+  const parser = new DOMParser();
+  const doc = parser.parseFromString(html, "text/html");
+  
+  // Remove script tags and event handlers
+  const scripts = doc.querySelectorAll("script");
+  scripts.forEach(script => script.remove());
+  
+  // Remove all event handler attributes (onclick, onload, etc.)
+  const allElements = doc.querySelectorAll("*");
+  allElements.forEach(element => {
+    Array.from(element.attributes).forEach(attr => {
+      if (attr.name.startsWith("on") || attr.name.startsWith("on")) {
+        element.removeAttribute(attr.name);
+      }
+    });
+  });
+  
+  // Sanitize elements
+  sanitizeNode(doc.body, opts);
+  
+  return doc.body.innerHTML;
+}
+
+function sanitizeNode(node: Node, options: SanitizeOptions): void {
+  if (node.nodeType === Node.ELEMENT_NODE) {
+    const element = node as Element;
+    const tagName = element.tagName.toLowerCase();
+    
+    // Remove disallowed tags
+    if (!options.allowedTags.includes(tagName)) {
+      // Replace with text content
+      const text = document.createTextNode(element.textContent || "");
+      element.parentNode?.replaceChild(text, element);
+      return;
+    }
+    
+    // Sanitize attributes
+    const allowedAttrs = [
+      ...(options.allowedAttributes[tagName] || []),
+      ...(options.allowedAttributes["*"] || [])
+    ];
+    
+    Array.from(element.attributes).forEach(attr => {
+      if (!allowedAttrs.includes(attr.name.toLowerCase())) {
+        element.removeAttribute(attr.name);
+        return;
+      }
+      
+      // Sanitize attribute values
+      if (attr.name === "href" || attr.name === "src") {
+        const value = attr.value.toLowerCase();
+        const hasValidScheme = options.allowedSchemes.some(scheme => 
+          value.startsWith(scheme + ":")
+        );
+        if (!hasValidScheme && !value.startsWith("/") && !value.startsWith("#")) {
+          element.removeAttribute(attr.name);
+        }
+      }
+      
+      if (attr.name === "style") {
+        element.setAttribute("style", sanitizeStyle(attr.value, options.allowedStyles));
+      }
+      
+      if (attr.name === "target" && attr.value === "_blank") {
+        element.setAttribute("rel", "noopener noreferrer");
+      }
+    });
+    
+    // Recursively sanitize children
+    Array.from(element.childNodes).forEach(child => sanitizeNode(child, options));
+  }
+}
+
+function sanitizeStyle(style: string, allowedStyles: string[]): string {
+  return style
+    .split(";")
+    .map(rule => rule.trim())
+    .filter(rule => {
+      const [property] = rule.split(":").map(s => s.trim().toLowerCase());
+      return allowedStyles.some(allowed => 
+        property === allowed || property.startsWith(allowed + "-")
+      );
+    })
+    .join("; ");
+}
diff --git a/src/utils/sanitize-attribute.ts b/src/utils/sanitize-attribute.ts
