@@ -0,0 +1,35 @@
+/**
+ * Attribute value sanitization to prevent attribute injection
+ */
+
+/**
+ * Sanitizes an attribute value to prevent HTML attribute injection
+ * Removes quotes, angle brackets, and other dangerous characters
+ */
+export function sanitizeAttribute(value: string): string {
+  return value
+    .replace(/["'`]/g, "") // Remove quotes that could break out of attribute
+    .replace(/[<>]/g, "")  // Remove angle brackets
+    .replace(/\s+/g, " ")  // Normalize whitespace
+    .trim();
+}
+
+/**
+ * Sanitizes a sandbox attribute value specifically
+ * Only allows known sandbox flags
+ */
+export function sanitizeSandbox(value: string): string {
+  const allowedFlags = [
+    "allow-scripts",
+    "allow-forms",
+    "allow-same-origin",
+    "allow-popups",
+    "allow-popups-to-escape-sandbox",
+    "allow-modals",
+    "allow-orientation-lock",
+    "allow-pointer-lock",
+    "allow-presentation",
+    "allow-top-navigation",
+    "allow-top-navigation-by-user-activation",
+    "allow-downloads"
+  ];
+  
+  return value
+    .split(/\s+/)
+    .filter(flag => allowedFlags.includes(flag.trim()))
+    .join(" ");
+}
